```jsx
import { useState, useEffect } from 'react';

function UserList() {
    const [users, setUsers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        fetch('/api/users')
            .then(res => {
                if (!res.ok) throw new Error('Failed to fetch');
                return res.json();
            })
            .then(data => setUsers(data))
            .catch(err => setError(err.message))
            .finally(() => setLoading(false));
    }, []);  // Empty array = run once on mount

    if (loading) return <p>Loading...</p>;
    if (error) return <p>Error: {error}</p>;

    return (
        <ul>
            {users.map(u => <li key={u.id}>{u.name}</li>)}
        </ul>
    );
}
```

Always handle three states: loading, error, and success. The empty dependency array `[]` ensures the fetch runs only once when the component mounts.

```javascript
import express from 'express';
const app = express();
app.use(express.json());

let users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
];

app.get('/api/users', (req, res) => {
    res.json(users);
});

app.get('/api/users/:id', (req, res) => {
    const user = users.find(u => u.id === parseInt(req.params.id));
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
});

app.post('/api/users', (req, res) => {
    const user = { id: users.length + 1, name: req.body.name };
    users.push(user);
    res.status(201).json(user);
});

app.delete('/api/users/:id', (req, res) => {
    users = users.filter(u => u.id !== parseInt(req.params.id));
    res.status(204).send();
});

app.listen(3000, () => console.log('Server on port 3000'));
```

This covers CRUD: GET for reading, POST for creating, DELETE for removing. Always use proper status codes: 200 OK, 201 Created, 204 No Content, 404 Not Found.

`useState` returns a state variable and a setter function. When you call the setter, React re-renders the component with the new value.

```jsx
import { useState } from 'react';

function Counter() {
    const [count, setCount] = useState(0);

    return (
        <div>
            <p>Count: {count}</p>
            <button onClick={() => setCount(count + 1)}>+1</button>
            <button onClick={() => setCount(prev => prev - 1)}>-1</button>
            <button onClick={() => setCount(0)}>Reset</button>
        </div>
    );
}
```

Key rules:
- `useState(0)` — initial value is `0`
- `setCount(5)` — set to exact value
- `setCount(prev => prev + 1)` — use callback when new state depends on previous
- State updates are **asynchronous** — reading `count` right after `setCount` shows the old value
- Each render has its own state snapshot

**Controlled components** — React state drives the form:

```jsx
import { useState } from 'react';

function LoginForm({ onSubmit }) {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!email || !password) {
            setError('All fields required');
            return;
        }
        setError('');
        onSubmit({ email, password });
    };

    return (
        <form onSubmit={handleSubmit}>
            {error && <p style={{color: 'red'}}>{error}</p>}
            <input
                type="email"
                value={email}
                onChange={e => setEmail(e.target.value)}
                placeholder="Email"
            />
            <input
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="Password"
            />
            <button type="submit">Login</button>
        </form>
    );
}
```

For complex forms with validation, use `react-hook-form` + `zod` — much less boilerplate and better performance since it uses uncontrolled inputs internally.

```javascript
import pg from 'pg';

const pool = new pg.Pool({
    host: process.env.DB_HOST || 'localhost',
    port: 5432,
    database: 'myapp',
    user: 'postgres',
    password: process.env.DB_PASSWORD,
    max: 20,  // Connection pool size
});

// Query
async function getUsers() {
    const result = await pool.query('SELECT * FROM users ORDER BY name');
    return result.rows;
}

// Parameterized query (prevents SQL injection!)
async function getUserById(id) {
    const result = await pool.query(
        'SELECT * FROM users WHERE id = $1',
        [id]
    );
    return result.rows[0] || null;
}

// Insert
async function createUser(name, email) {
    const result = await pool.query(
        'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
        [name, email]
    );
    return result.rows[0];
}

// In Express route
app.get('/api/users/:id', async (req, res) => {
    try {
        const user = await getUserById(req.params.id);
        if (!user) return res.status(404).json({ error: 'Not found' });
        res.json(user);
    } catch (err) {
        res.status(500).json({ error: 'Database error' });
    }
});
```

Always use parameterized queries (`$1, $2`) — never concatenate user input into SQL strings.

```javascript
import jwt from 'jsonwebtoken';
import bcrypt from 'bcrypt';

const SECRET = process.env.JWT_SECRET;

// Login endpoint
app.post('/api/login', async (req, res) => {
    const { email, password } = req.body;
    const user = await getUserByEmail(email);
    if (!user || !await bcrypt.compare(password, user.password_hash)) {
        return res.status(401).json({ error: 'Invalid credentials' });
    }
    const token = jwt.sign(
        { id: user.id, email: user.email },
        SECRET,
        { expiresIn: '24h' }
    );
    res.json({ token, user: { id: user.id, name: user.name } });
});

// Auth middleware
function authenticate(req, res, next) {
    const token = req.headers.authorization?.replace('Bearer ', '');
    if (!token) return res.status(401).json({ error: 'No token' });
    try {
        req.user = jwt.verify(token, SECRET);
        next();
    } catch {
        res.status(401).json({ error: 'Invalid token' });
    }
}

// Protected route
app.get('/api/profile', authenticate, async (req, res) => {
    const user = await getUserById(req.user.id);
    res.json(user);
});
```

Flow: user logs in → gets JWT → sends it in `Authorization: Bearer <token>` header → middleware verifies → route handler accesses `req.user`.

**CSR (Client-Side Rendering):** Browser downloads empty HTML + JavaScript. JS fetches data and renders the page. Slower initial load, good for dashboards.

**SSR (Server-Side Rendering):** Server renders full HTML on each request. Fast first paint, good for SEO. Use `getServerSideProps`:
```jsx
export async function getServerSideProps() {
    const res = await fetch('https://api.example.com/posts');
    const posts = await res.json();
    return { props: { posts } };
}
```

**SSG (Static Site Generation):** HTML generated at build time. Fastest — served from CDN. Use `getStaticProps`:
```jsx
export async function getStaticProps() {
    const posts = await fetchPosts();
    return { props: { posts }, revalidate: 3600 }; // ISR: rebuild every hour
}
```

**When to use:**
- SSG: blog posts, docs, marketing pages (content rarely changes)
- SSR: user-specific pages, real-time data, search results
- CSR: authenticated dashboards, highly interactive apps
- ISR (Incremental Static Regeneration): SSG that updates periodically — best of both worlds

