useContext shares state across components without prop drilling (passing props through many levels).

```jsx
import { createContext, useContext, useState } from 'react';

const ThemeContext = createContext();

function ThemeProvider({ children }) {
    const [theme, setTheme] = useState('dark');
    const toggle = () => setTheme(t => t === 'dark' ? 'light' : 'dark');
    return (
        <ThemeContext.Provider value={{ theme, toggle }}>
            {children}
        </ThemeContext.Provider>
    );
}

function useTheme() {
    const ctx = useContext(ThemeContext);
    if (!ctx) throw new Error('useTheme must be inside ThemeProvider');
    return ctx;
}

// Any nested component can access theme
function Header() {
    const { theme, toggle } = useTheme();
    return (
        <header style={{ background: theme === 'dark' ? '#333' : '#fff' }}>
            <button onClick={toggle}>Toggle Theme</button>
        </header>
    );
}

// Wrap app
function App() {
    return (
        <ThemeProvider>
            <Header />
            <Main />
        </ThemeProvider>
    );
}
```

Use Context for: theme, auth state, locale. Don't use it for frequently changing state (causes re-renders) — use Zustand or Redux for that.

