Middleware is a function that runs BETWEEN receiving a request and sending a response. It can modify req/res, end the request, or pass to the next middleware.

```javascript
// Logging middleware
function logger(req, res, next) {
    console.log(`${req.method} ${req.path}`);
    const start = Date.now();
    res.on('finish', () => {
        console.log(`${res.statusCode} ${Date.now() - start}ms`);
    });
    next();  // Pass to next middleware/route
}

// Auth middleware
function requireAuth(req, res, next) {
    const token = req.headers.authorization;
    if (!token) return res.status(401).json({ error: 'No token' });
    try {
        req.user = jwt.verify(token.replace('Bearer ', ''), SECRET);
        next();
    } catch {
        res.status(401).json({ error: 'Invalid token' });
    }
}

// Apply globally
app.use(logger);
app.use(express.json());

// Apply to specific routes
app.get('/api/profile', requireAuth, getProfile);
app.get('/api/admin', requireAuth, requireRole('admin'), getAdmin);
```

Middleware runs in order. The chain: request → logger → json parser → auth → route handler → response. Call `next()` to continue or send a response to stop.

```jsx
import { BrowserRouter, Routes, Route, Link, useParams, useNavigate } from 'react-router-dom';

function App() {
    return (
        <BrowserRouter>
            <nav>
                <Link to="/">Home</Link>
                <Link to="/about">About</Link>
                <Link to="/users">Users</Link>
            </nav>
            <Routes>
                <Route path="/" element={<Home />} />
                <Route path="/about" element={<About />} />
                <Route path="/users" element={<UserList />} />
                <Route path="/users/:id" element={<UserDetail />} />
                <Route path="*" element={<h1>404 Not Found</h1>} />
            </Routes>
        </BrowserRouter>
    );
}

function UserDetail() {
    const { id } = useParams();  // Get URL parameter
    const navigate = useNavigate();
    return (
        <div>
            <h1>User {id}</h1>
            <button onClick={() => navigate('/users')}>Back</button>
        </div>
    );
}
```

`Link` for declarative navigation (replaces `<a>`), `useNavigate` for programmatic navigation, `useParams` to read URL parameters. The `*` route catches all unmatched URLs as a 404 page.
